 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # In each row, fill the single background cell separating alternating
    # instances of the same foreground color, when the gap is bounded by marks.
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    for r, row in enumerate(grid):
        marks = [c for c, x in enumerate(row) if x != bg]
        if len(marks) > 1:
            color = grid[r][marks[0]]
            if all(grid[r][c] == color for c in marks):
                for a, b in zip(marks, marks[1:]):
                    for c in range(a + 1, b):
                        if grid[r][c] == bg:
                            out[r][c] = 2
    return out

